{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximize the number of complete products (each requiring one of each component), minimize total production hours, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting examples but requiring one specific answer."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the production rates in the table (e.g., Workshop A makes 10 units/hour of Component 1) the same for every workshop-component pair, or does each workshop have its own rate for each component?"
  ],
  "rationale": "The response asks a single clarification question regarding the structure of the production rates, presenting a binary choice that constitutes one independent semantic query."
}

